corpus_block("test-coord-transform.R: coord_transform() expands axes identically to coord_cartesian()", {
  .plot("test-coord-transform.R: coord_transform() expands axes identically to coord_cartesian() #1", p <- ggplot(mpg, aes(class, hwy)) + geom_point())
  .plot("test-coord-transform.R: coord_transform() expands axes identically to coord_cartesian() #2", p + coord_cartesian())
  built_cartesian <- ggplot_build(p + coord_cartesian())
  .plot("test-coord-transform.R: coord_transform() expands axes identically to coord_cartesian() #3", p + coord_transform())
  built_trans <- ggplot_build(p + coord_transform())
  cartesian_params <- built_cartesian@layout$panel_params[[1]]
  trans_params <- built_trans@layout$panel_params[[1]]
})

